import{_ as l,k as e,q as i,au as r}from"./chunks/framework.DE363VfD.js";const f=JSON.parse('{"title":"什么是 Protocol Launcher？","description":"","frontmatter":{"layout":"doc"},"headers":[],"relativePath":"zh/guide/what-is-it.md","filePath":"zh/guide/what-is-it.md"}'),t={name:"zh/guide/what-is-it.md"};function p(h,a,s,o,m,d){return i(),e("div",null,[...a[0]||(a[0]=[r('<div style="display:none;" hidden="true" aria-hidden="true">Are you an LLM? You can read better optimized documentation at /protocol-launcher/zh/guide/what-is-it.md for this page in Markdown format</div><h1 id="什么是-protocol-launcher" tabindex="-1">什么是 Protocol Launcher？ <a class="header-anchor" href="#什么是-protocol-launcher" aria-label="Permalink to “什么是 Protocol Launcher？”">​</a></h1><p><strong>Protocol Launcher</strong> 是一个 TypeScript 库，旨在为各种应用程序生成“快速启动” URL（深度链接）。</p><p>这些 URL 允许用户通过单击触发应用程序中的特定操作，例如安装插件、配置服务器或设置 API 密钥。</p><h2 id="主要特性" tabindex="-1">主要特性 <a class="header-anchor" href="#主要特性" aria-label="Permalink to “主要特性”">​</a></h2><ul><li><strong>类型安全</strong>: 严格的 TypeScript 类型校验，避免生成不合法链接。</li><li><strong>多应用支持</strong>: 可扩展设计，基于 URL Scheme 支持更多应用。</li><li><strong>按需加载/可树摇</strong>: 仅按需导入所需功能，减小打包体积。</li><li><strong>安全编码</strong>: 对配置进行安全编码，避免注入。完美支持中文等 Unicode 字符。</li><li><strong>零运行时依赖</strong>: 轻量、无外部运行时依赖。</li><li><strong>ESM 优先</strong>: 现代 ES Modules，适配 Node 与各类打包器。</li></ul><h2 id="支持的应用程序" tabindex="-1">支持的应用程序 <a class="header-anchor" href="#支持的应用程序" aria-label="Permalink to “支持的应用程序”">​</a></h2><p>目前，我们支持以下应用程序：</p><ul><li><a href="./../apps/affine.html">AFFiNE</a></li><li><a href="./../apps/alfred.html">Alfred</a></li><li><a href="./../apps/antigravity.html">Antigravity</a></li><li><a href="./../apps/app-store.html">App Store</a></li><li><a href="./../apps/appflowy.html">AppFlowy</a></li><li><a href="./../apps/apple-map.html">Apple Map</a></li><li><a href="./../apps/apple-script.html">Apple Script Editor</a></li><li><a href="./../apps/atom.html">Atom</a></li><li><a href="./../apps/bbedit.html">BBEdit</a></li><li><a href="./../apps/bear.html">Bear</a></li><li><a href="./../apps/cherry-studio.html">Cherry Studio</a></li><li><a href="./../apps/code-buddy.html">CodeBuddy</a></li><li><a href="./../apps/code-buddy-cn.html">CodeBuddy China</a></li><li><a href="./../apps/code-runner.html">CodeRunner</a></li><li><a href="./../apps/codelite.html">CodeLite</a></li><li><a href="./../apps/codex.html">Codex</a></li><li><a href="./../apps/cursor.html">Cursor</a></li><li><a href="./../apps/evernote.html">Evernote</a></li><li><a href="./../apps/fsnotes.html">FSNotes</a></li><li><a href="./../apps/github-desktop.html">GitHub Desktop</a></li><li><a href="./../apps/goland.html">GoLand</a></li><li><a href="./../apps/hbuilderx.html">HBuilderX</a></li><li><a href="./../apps/idea.html">IntelliJ IDEA</a></li><li><a href="./../apps/itsycal.html">Itsycal</a></li><li><a href="./../apps/jump-desktop.html">Jump Desktop</a></li><li><a href="./../apps/kaleidoscope.html">Kaleidoscope</a></li><li><a href="./../apps/kiro.html">Kiro</a></li><li><a href="./../apps/lingma.html">Lingma</a></li><li><a href="./../apps/macos.html">macOS</a></li><li><a href="./../apps/macvim.html">MacVim</a></li><li><a href="./../apps/microsoft-edge.html">Microsoft Edge</a></li><li><a href="./../apps/motrix.html">Motrix</a></li><li><a href="./../apps/navicat.html">Navicat</a></li><li><a href="./../apps/nova.html">Nova</a></li><li><a href="./../apps/opencode.html">OpenCode</a></li><li><a href="./../apps/orchids.html">Orchids</a></li><li><a href="./../apps/pearai.html">PearAI</a></li><li><a href="./../apps/pika.html">Pika</a></li><li><a href="./../apps/phpstorm.html">PhpStorm</a></li><li><a href="./../apps/pycharm.html">PyCharm</a></li><li><a href="./../apps/qoder.html">Qoder</a></li><li><a href="./../apps/quark.html">Quark</a></li><li><a href="./../apps/rustrover.html">RustRover</a></li><li><a href="./../apps/shortcuts.html">Shortcuts</a></li><li><a href="./../apps/sketch.html">Sketch</a></li><li><a href="./../apps/soulver.html">Soulver</a></li><li><a href="./../apps/sourcetree.html">SourceTree</a></li><li><a href="./../apps/telegram.html">Telegram</a></li><li><a href="./../apps/termius.html">Termius</a></li><li><a href="./../apps/textmate.html">TextMate</a></li><li><a href="./../apps/theia.html">Theia</a></li><li><a href="./../apps/things.html">Things</a></li><li><a href="./../apps/thunder.html">Thunder</a></li><li><a href="./../apps/trae.html">Trae</a></li><li><a href="./../apps/trae-cn.html">Trae China</a></li><li><a href="./../apps/verdent.html">Verdent</a></li><li><a href="./../apps/vscode.html">VS Code</a></li><li><a href="./../apps/vscode-insiders.html">VS Code Insiders</a></li><li><a href="./../apps/vscodium.html">VSCodium</a></li><li><a href="./../apps/webstorm.html">WebStorm</a></li><li><a href="./../apps/wemeet.html">WeMeet</a></li><li><a href="./../apps/windsurf.html">Windsurf</a></li><li><a href="./../apps/xcode.html">Xcode</a></li><li><a href="./../apps/zed.html">Zed</a></li></ul><p>未来将添加更多应用程序。</p>',10)])])}const c=l(t,[["render",p]]);export{f as __pageData,c as default};
